#!/bin/sh
# PeDitX-AI single-file installer for OpenWrt/PeDitXOS.
# Usage on the router (as root):
#   cat > /tmp/peditx-ai-installer.sh && sh /tmp/peditx-ai-installer.sh
set -eu

DEST=/opt/peditx-ai

if [ "$(id -u)" -ne 0 ]; then
    echo "Run this installer as root over SSH." >&2
    exit 2
fi
if [ ! -r /etc/openwrt_release ] && [ ! -r /etc/openwrt_version ]; then
    echo "This installer targets OpenWrt/PeDitXOS only." >&2
    exit 2
fi

mkdir -p "$DEST" /usr/bin
AVAILABLE_KB=$(df -Pk /overlay | awk 'NR == 2 { print $4 }')
case "$AVAILABLE_KB" in
    ''|*[!0-9]*) echo "Could not read free space on /overlay; continuing and letting the package manager check." ;;
    *) printf 'Free space on /overlay (extroot) before dependency install: %s KiB\n' "$AVAILABLE_KB" ;;
esac

if command -v apk >/dev/null 2>&1; then
    printf '%s\n' "Updating package indexes with apk..."
    if ! apk update; then
        echo "apk could not update package indexes. Check the package feeds and internet access, then retry." >&2
        exit 1
    fi
    printf '%s\n' "Installing Python dependencies with apk..."
    if ! apk add python3-light python3-email python3-urllib python3-openssl python3-codecs ca-bundle; then
        echo "OpenWrt could not install the required Python packages. Check the package feeds, internet access, and free overlay space, then retry." >&2
        exit 1
    fi
    printf '%s\n' "APK dependencies installed."
elif command -v opkg >/dev/null 2>&1; then
    printf '%s\n' "Updating package indexes with opkg..."
    if ! opkg update; then
        echo "opkg could not update package indexes. Check the package feeds and internet access, then retry." >&2
        exit 1
    fi
    printf '%s\n' "Installing Python dependencies with opkg..."
    if ! opkg install python3-light python3-email python3-urllib python3-openssl python3-codecs ca-bundle; then
        echo "opkg could not install the required Python packages. Check the package feeds and free overlay space, then retry." >&2
        exit 1
    fi
    printf '%s\n' "OPKG dependencies installed."
else
    echo "Could not find OpenWrt's apk or opkg package manager." >&2
    exit 2
fi

PYTHON=$(command -v python3 || true)
[ -n "$PYTHON" ] || { echo "Python 3 was not installed by the package manager." >&2; exit 1; }
if ! "$PYTHON" -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 10) else 1)'; then
    echo "PeDitX-AI requires Python 3.10 or newer." >&2
    exit 1
fi

# Extract the embedded payload: one "path=base64" line per file, relative to $DEST.
sed -n '/^#PAYLOAD-BEGIN$/,/^#PAYLOAD-END$/p' "$0" | sed '1d;$d' | while IFS='=' read -r rel data; do
    [ -n "$rel" ] || continue
    mkdir -p "$DEST/$(dirname "$rel")"
    printf '%s' "$data" | "$PYTHON" -c 'import base64,sys,os; p=sys.argv[1]; os.makedirs(os.path.dirname(p) or ".", exist_ok=True); open(p,"wb").write(base64.b64decode(sys.stdin.read()))' "$DEST/$rel"
    chmod 0644 "$DEST/$rel"
done

cat > /usr/bin/assist <<EOF
#!/bin/sh
APP="$DEST/peditx_ai.py"
case "\${1:-}" in
    --configure|--models|--choose-model|--mode) exec "$PYTHON" "\$APP" "\$@" ;;
    *) exec "$PYTHON" "\$APP" --cli "\$@" ;;
esac
EOF
chmod 0755 /usr/bin/assist

# LuCI control page
mkdir -p /usr/share/luci/menu.d /usr/share/rpcd/acl.d \
    /www/luci-static/resources/view/peditx-ai /etc/init.d
cp "$DEST/luci-app-peditx-ai/menu.d/peditx-ai.json" /usr/share/luci/menu.d/peditx-ai.json
cp "$DEST/luci-app-peditx-ai/acl.d/peditx-ai.json"  /usr/share/rpcd/acl.d/peditx-ai.json
cp "$DEST/luci-app-peditx-ai/view/main.js"          /www/luci-static/resources/view/peditx-ai/main.js
cp "$DEST/luci-app-peditx-ai/root/etc/init.d/peditx-ai" /etc/init.d/peditx-ai
chmod 0644 /usr/share/luci/menu.d/peditx-ai.json /usr/share/rpcd/acl.d/peditx-ai.json \
    /www/luci-static/resources/view/peditx-ai/main.js
chmod 0755 /etc/init.d/peditx-ai
rm -rf "$DEST/luci-app-peditx-ai"

if [ ! -f /etc/config/peditx_ai ]; then
    printf "config peditx_ai 'main'\n\toption expose_wan '0'\n\n" > /etc/config/peditx_ai
    chmod 0600 /etc/config/peditx_ai
fi

/etc/init.d/peditx-ai enable
/etc/init.d/peditx-ai restart

rm -rf /tmp/luci-modulecache/* 2>/dev/null || true
rm -f /tmp/luci-indexcache* 2>/dev/null || true
/etc/init.d/rpcd restart

printf '%s\n' "PeDitX-AI installed in $DEST." "Run 'assist' over SSH for the CLI." \
    "Open LuCI -> AI -> PeDitX-AI for the control page and web UI." \
    "Remote Git sync and skill install need Git installed separately."
exit 0
#PAYLOAD-BEGIN
src/peditx_ai.
web/index.
web/sw.
web/manifest.
assets/peditx-ai.
assets/pwa-icons/android-192.
assets/pwa-icons/android-512.
assets/pwa-icons/apple-touch-icon.
luci-app-peditx-ai/menu.d/peditx-ai.
luci-app-peditx-ai/acl.d/peditx-ai.
luci-app-peditx-ai/view/main.
luci-app-peditx-ai/root/etc/init.d/peditx-
#PAYLOAD-END
